def _nucmer_hits_to_percent_identity(nucmer_hits):
        """Input is hits made by self._parse_nucmer_coords_file.
           Returns dictionary. key = contig name. Value = percent identity of hits to that contig"""
           percent_identity_dict = {}
           for hit in nucmer_hits:
               if hit[0] not in percent_identity_dict:
                   percent_identity_dict[hit[0]] = hit[1]
               else:
                   percent_identity_dict[hit[0]] += hit[1]
           for key in percent_identity_dict:
               percent_identity_dict[key] = percent_identity_dict[key] / len(nucmer_hits)
           return percent_identity_dict

